namespace ghidra.app.plugin.core.label;

using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.util;
using ghidra.util.task;
using ghidra.util.task;







public class LabelHistoryTask : Task {
	private Pattern regexp;
	private string dialogTitle;
	private List<LabelHistory> historyList;
	private Program program;
	private PluginTool tool;

	LabelHistoryTask(PluginTool tool, Program program, string matchStr) : base("Get All Label History", true, false, true)
    {
		this.tool = tool;
		this.program = program;
		if (matchStr != null) {
			regexp = UserSearchUtils.createSearchPattern(matchStr, false);
			dialogTitle = "Label History Matching " + matchStr;
		}
		else {
			dialogTitle = "All Label History";
		}
	}

	/* @Override */
	public void run(TaskMonitor monitor) {
		SymbolTable st = program.getSymbolTable();
		historyList = new List<LabelHistory>();
		Iterator<LabelHistory> iter = st.getLabelHistory();
		int count = 0;
		while (iter.hasNext()) {
			LabelHistory h = iter.next();
			if (regexp != null) {
				Matcher matcher = regexp.matcher(h.getLabelString());
				if (matcher.find()) {
					historyList.add(h);
				}
			}
			else {
				historyList.add(h);
			}
			++count;
			if (count == 50) {
				count = 0;
				if (monitor.isCancelled()) {
					break;
				}
			}
		}

		base.notifyTaskListeners(monitor.isCancelled());

		SwingUtilities.invokeLater(new _Anon_Runnable_1());
	}

	bool labelsFound() {
		return historyList.size() > 0;
	}

	internal class _Anon_Runnable_1 : Runnable
	{

			/* @Override */
			public void run() {
				if (!monitor.isCancelled()) {
					if (historyList.size() > 0) {
						LabelHistoryDialog dialog =
							new LabelHistoryDialog(tool, program, dialogTitle, historyList);
						tool.showDialog(dialog);
					}
				}
			}
		
	}

}
